{
  "implementation": "import math
def solve(case):
    matrix = case['matrix']
    if not matrix:
        return {"idf": [], "row_degree": [], "weighted_matrix": []}
    rows = len(matrix)
    cols = len(matrix[0])
    row_degree = [sum(row) for row in matrix]
    df = [sum(1 for row in matrix if row[j] > 0) for j in range(cols)]
    N = rows
    idf = [math.log(N / df[j]) if df[j] > 0 else 0.0 for j in range(cols)]
    weighted_matrix = [[row[j] * idf[j] for j in range(cols)] for row in matrix]
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted_matrix}"
}
